#!/usr/bin/env node
// Regenerates src/agent/playbooks.ts from the markdown sources in
// src/agent/playbooks/*.md.
//
// Why this exists: Workers cannot import .md at runtime here because
// wrangler.jsonc has no `rules: [{ type: "Text" }]` entry (that file belongs
// to another owner in this branch). The markdown stays the human-edited
// source of truth; this script compiles it into a plain TS module of string
// constants that bundles like any other module. tests/playbooks-sync.test.ts
// re-parses the markdown independently and fails `npm run check` if this
// generated file has drifted, so a forgotten `npm run playbooks:build` is
// caught in CI rather than silently shipping a stale prompt.
//
// Run after editing any file in src/agent/playbooks/:
//   npm run playbooks:build

import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import path from "node:path";

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, "..");
const playbooksDir = path.join(root, "src/agent/playbooks");
const outFile = path.join(root, "src/agent/playbooks.ts");

const FILES = ["weekly-plan.md", "decompose-assignment.md", "forum-brief.md"];

function parsePlaybook(raw, file) {
  const match = raw.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);
  if (!match) {
    throw new Error(`${file}: missing a leading "---" header block.`);
  }
  const [, header, body] = match;
  const fields = Object.fromEntries(
    header
      .split("\n")
      .filter((line) => line.trim().length > 0)
      .map((line) => {
        const index = line.indexOf(":");
        if (index < 0) {
          throw new Error(`${file}: malformed header line "${line}".`);
        }
        return [line.slice(0, index).trim(), line.slice(index + 1).trim()];
      }),
  );
  for (const key of ["id", "title", "trigger", "output"]) {
    if (!fields[key]) {
      throw new Error(`${file}: header is missing "${key}".`);
    }
  }
  return { id: fields.id, title: fields.title, trigger: fields.trigger, output: fields.output, procedure: body.trim() };
}

function escapeTemplate(text) {
  return text.replace(/\\/g, "\\\\").replace(/`/g, "\\`").replace(/\$\{/g, "\\${");
}

function main() {
  const playbooks = FILES.map((file) => parsePlaybook(readFileSync(path.join(playbooksDir, file), "utf8"), file));

  const entries = playbooks
    .map(
      (playbook) => `  {
    id: ${JSON.stringify(playbook.id)},
    title: ${JSON.stringify(playbook.title)},
    trigger: ${JSON.stringify(playbook.trigger)},
    output: ${JSON.stringify(playbook.output)},
    procedure: \`${escapeTemplate(playbook.procedure)}\`,
  },`,
    )
    .join("\n");

  const output = `// AUTO-GENERATED by scripts/build-playbooks.mjs from src/agent/playbooks/*.md.
// Do not edit by hand — edit the markdown, then run \`npm run playbooks:build\`.
// tests/playbooks-sync.test.ts fails \`npm run check\` if this drifts from the markdown.

export type PlaybookId = "weekly-plan" | "decompose-assignment" | "forum-brief";

export interface Playbook {
  id: PlaybookId;
  title: string;
  trigger: string;
  output: string;
  procedure: string;
}

export const PLAYBOOKS: Playbook[] = [
${entries}
];
`;

  writeFileSync(outFile, output);
  console.log(`Wrote ${path.relative(root, outFile)} from ${FILES.length} playbook(s).`);
}

main();
